56: export function selectClip(s:MotionSample):{name:string;time:number}{
57:  const p=clamp(s.phase);let name='Idle_Loop',time=0;
58:  if(s.action==='walk'){name=s.gait==='walk'?'Walk_Loop':'Jog_Fwd_Loop';time=((s.phase%1+1)%1)*clips.get(name)!.duration;}
59:  else if(s.action==='attack'){
60:   name=s.hammer?'Sword_Attack':s.variant==='reverse'?'Strike_B':s.variant==='overhead'?'Sword_Regular_C':s.variant==='thrust'?'Sword_Dash':'Strike_A';
61:   // Match the authored contact pose to the server's windup boundary (phase .5).
62:   const contact:Record<string,number>={Strike_A:.24,Strike_B:.25,Sword_Regular_C:.62,Sword_Dash:.30,Sword_Attack:.40};const c=contact[name],duration=clips.get(name)!.duration;
63:   time=p<.5?p*2*c:c+(p-.5)*2*(duration-c);
64:  }else if(s.action==='dodge'){name='Roll';time=p*clips.get(name)!.duration;}
65:  else if((s.action==='guard'||s.action==='charge')&&s.locomotionPhase!==undefined){name=s.action==='guard'?'Guard_Walk':'Charge_Walk';time=((s.locomotionPhase%1+1)%1)*clips.get(name)!.duration;}
66:  else if(s.action==='guard'){name='Sword_Block';time=.33;}
67:  else if(s.action==='charge'){name='Sword_Attack';time=.08+p*.32;}
68:  else if(s.action==='hurt'){name='Hit_Chest';time=p*clips.get(name)!.duration;}
69:  else{name='Idle_Loop';time=(s.clock*.001)%clips.get(name)!.duration;}

